#pragma once
#include <math.h>

typedef enum { ROVER_PATH_CLEAR, ROVER_PATH_BLOCKED, ROVER_PATH_CROWDED, ROVER_PATH_WET_FLOOR } rover_path_t;
typedef struct {
    float battery; /* % */
    float front_obstacle_m;
    float goal_m;
    rover_path_t path;
    int carrying_load;
} rover_state;

#define ROVER_N_IN 8
static inline void rover_features(const rover_state *s, float *x) {
    int i = 0;
    x[i++] = (s->battery - (0.0f)) / (100.0f);
    x[i++] = (s->front_obstacle_m - (0.0f)) / (8.0f);
    x[i++] = (s->goal_m - (0.0f)) / (60.0f);
    for (int k = 0; k < 4; k++) x[i++] = ((int)s->path == k) ? 1.f : 0.f;
    x[i++] = s->carrying_load ? 1.f : 0.f;
    (void)i;
}

static inline void sparrow_pico_dense(const float *w, const float *b, const float *x, int n_in, int n_out,
                                      int relu, float *y) {
    for (int o = 0; o < n_out; o++) {
        float a = b[o];
        for (int i = 0; i < n_in; i++) a += w[o * n_in + i] * x[i];
        y[o] = relu && a < 0 ? 0 : a;
    }
}

