static inline void rover_action(const rover_state *s, float *probs) {
    float x[ROVER_N_IN], h0[32], h1[32], m = -1e30f, z = 0;
    rover_features(s, x);
    sparrow_pico_dense(rover_action_w0, rover_action_b0, x, ROVER_N_IN, 32, 1, h0);
    sparrow_pico_dense(rover_action_w1, rover_action_b1, h0, 32, 32, 1, h1);
    sparrow_pico_dense(rover_action_w2, rover_action_b2, h1, 32, 5, 0, probs);
    for (int i = 0; i < 5; i++) if (probs[i] > m) m = probs[i];
    for (int i = 0; i < 5; i++) z += (probs[i] = expf(probs[i] - m));
    for (int i = 0; i < 5; i++) probs[i] /= z;
}
