#define ROVER_RISK_N 4
static inline void rover_risk(const rover_state *s, float *probs) {
    float x[ROVER_N_IN], h0[32], h1[32], m = -1e30f, z = 0;
    rover_features(s, x);
    sparrow_pico_dense(rover_risk_w0, rover_risk_b0, x, ROVER_N_IN, 32, 1, h0);
    sparrow_pico_dense(rover_risk_w1, rover_risk_b1, h0, 32, 32, 1, h1);
    sparrow_pico_dense(rover_risk_w2, rover_risk_b2, h1, 32, 4, 0, probs);
    for (int i = 0; i < 4; i++) if (probs[i] > m) m = probs[i];
    for (int i = 0; i < 4; i++) z += (probs[i] = expf(probs[i] - m));
    for (int i = 0; i < 4; i++) probs[i] /= z;
}
